  // --------------------------------------------------------------------------
  // 比对：每拍每变体比一根打包向量；只有失配才逐位扫描定位到端口
  // --------------------------------------------------------------------------
  task automatic report_diff(input string mod, input logic [NOW-1:0] g,
                             input logic [NOW-1:0] x);
    string last = "";
    for (int b = 0; b < NOW; b++)
      if (g[b] !== x[b] && port_of_bit[b] != last) begin
        last = port_of_bit[b];
        if (errors < 40)
          $display("MISMATCH t=%0t %s.%s (bit %0d) golden=%b xs=%b",
                   $time, mod, port_of_bit[b], b, g[b], x[b]);
      end
  endtask

  always @(posedge clk) begin
    if (cmp_en && !rst) begin
      checks++;
      if (g_e0_all !== x_e0_all) begin
        errors++;
        report_diff("UncacheEntry", g_e0_all, x_e0_all);
      end
      checks++;
      if (g_e1_all !== x_e1_all) begin
        errors++;
        report_diff("UncacheEntry_1", g_e1_all, x_e1_all);
      end
      checks++;
      if (g_e2_all !== x_e2_all) begin
        errors++;
        report_diff("UncacheEntry_2", g_e2_all, x_e2_all);
      end
      checks++;
      if (g_e3_all !== x_e3_all) begin
        errors++;
        report_diff("UncacheEntry_3", g_e3_all, x_e3_all);
      end
      checks++;
      if (g_e4_all !== x_e4_all) begin
        errors++;
        report_diff("UncacheEntry_4", g_e4_all, x_e4_all);
      end
      checks++;
      if (g_e5_all !== x_e5_all) begin
        errors++;
        report_diff("UncacheEntry_5", g_e5_all, x_e5_all);
      end
      checks++;
      if (g_e6_all !== x_e6_all) begin
        errors++;
        report_diff("UncacheEntry_6", g_e6_all, x_e6_all);
      end
      checks++;
      if (g_e7_all !== x_e7_all) begin
        errors++;
        report_diff("UncacheEntry_7", g_e7_all, x_e7_all);
      end
      checks++;
      if (g_e8_all !== x_e8_all) begin
        errors++;
