      end
      checks++;
      if (g_e12_all !== x_e12_all) begin
        errors++;
        report_diff("UncacheEntry_12", g_e12_all, x_e12_all);
      end
      checks++;
      if (g_e13_all !== x_e13_all) begin
        errors++;
        report_diff("UncacheEntry_13", g_e13_all, x_e13_all);
      end
      checks++;
      if (g_e14_all !== x_e14_all) begin
        errors++;
        report_diff("UncacheEntry_14", g_e14_all, x_e14_all);
      end
      checks++;
      if (g_e15_all !== x_e15_all) begin
        errors++;
        report_diff("UncacheEntry_15", g_e15_all, x_e15_all);
      end
    end
  end

  // 覆盖统计用 golden 侧条目的层次引用（只用于计数，不参与判决）。
  always @(posedge clk) if (!rst && cmp_en) begin
    if (!u_g_e0.flush && io_req_valid && u_g_e0.req_valid) cov_enq_on_busy++;
    if (u_g_e0.uncacheState == 2'h1) cov_state_req++;
    if (u_g_e0.uncacheState == 2'h2) cov_state_resp++;
    if (u_g_e0.uncacheState == 2'h3) cov_state_wait++;
    if (io_uncache_req_ready && g_e0_io_uncache_req_valid) cov_uncache_req_fire++;
    if (io_mmioOut_ready && g_e0_io_mmioOut_valid) cov_mmio_wb++;
    if (io_ncOut_ready && g_e0_io_ncOut_valid) cov_nc_wb++;
    if (u_g_e0.slaveAck) cov_slave_ack_e0++;
    if (u_g_e15.slaveAck) cov_slave_ack_e15++;
    if (io_uncache_idResp_valid && io_uncache_idResp_bits_mid > 7'd15) cov_slave_miss++;
    if (u_g_e0.needFlush && u_g_e0.uncacheState inside {2'h0, 2'h1}) cov_flush_idle++;
    if (u_g_e0.needFlushReg && u_g_e0.uncacheState == 2'h2) cov_flush_deferred++;
    if (u_g_e0.needFlush && u_g_e0.uncacheState == 2'h3) cov_flush_wait++;
    if (io_redirect_valid && io_redirect_bits_level) cov_redirect_level++;
    if (io_uncache_resp_valid && io_uncache_resp_bits_denied) cov_resp_denied++;
    if (io_uncache_resp_valid && io_uncache_resp_bits_corrupt && !io_uncache_resp_bits_denied) cov_resp_corrupt++;
    if (u_g_e0.uncacheState == 2'h0 && u_g_e0.req_valid && !u_g_e0.req_nc && !(u_g_e0.pendingld_last_REG && {u_g_e0.req_uop_robIdx_flag, u_g_e0.req_uop_robIdx_value} == {u_g_e0.pendingPtr_next_r_flag, u_g_e0.pendingPtr_next_r_value})) cov_mmio_head_wait++;
    if (u_g_e0.uncacheState == 2'h0 && u_g_e0.req_valid && !u_g_e0.req_nc && u_g_e0.pendingld_last_REG && {u_g_e0.req_uop_robIdx_flag, u_g_e0.req_uop_robIdx_value} == {u_g_e0.pendingPtr_next_r_flag, u_g_e0.pendingPtr_next_r_value}) cov_mmio_head_hit++;
    if (g_e0_io_mmioSelect) cov_mmioselect++;
  end

  // --------------------------------------------------------------------------
  // 复位 / 暖机 / 收尾
  // --------------------------------------------------------------------------
  initial begin
    if ($value$plusargs("ncycles=%d", NCYCLES)) ;
    rst = 1'b1;
    warm_phase = 1;
    repeat (4) @(posedge clk);
    @(negedge clk) rst = 1'b0;
    // 1) 收请求：写满 190 个 payload 字段，并把 flushPipe/replayInst 压 0
    repeat (2) @(posedge clk);
    // 2) 16 拍 idResp：mid 依次取 0..15，让每个变体各认领一次写死 slaveId
    warm_phase = 2;
    for (int k = 0; k < 16; k++) begin
      warm_mid = k;
      @(posedge clk);
    end
    // 3) 一拍 resp：写死 uncacheData
    warm_phase = 3;
    repeat (2) @(posedge clk);
    warm_phase = 0;
    repeat (2) @(posedge clk);
    @(negedge clk) cmp_en = 1'b1;
    // ★中途反复打异步复位★：复位域的唯一把关手段（见文件头）。
    for (int k = 0; k < RESET_PULSES; k++) begin
      repeat (NCYCLES / RESET_PULSES) @(posedge clk);
      @(negedge clk) begin rst = 1'b1; cmp_en = 1'b0; end
      repeat (1 + (k % 3)) @(posedge clk);
      @(negedge clk) rst = 1'b0;
      repeat (2) @(posedge clk);
      @(negedge clk) cmp_en = 1'b1;
      cov_reset_pulses++;
    end

    $display("--- COVERAGE (每项必须 > 0，否则该机制没被激励到) ---");
    $display("  %-46s: %0d", "中途异步复位次数（复位域的唯一把关手段）", cov_reset_pulses);
    $display("  %-46s: %0d", "收新请求压过在飞请求（golden XSError 条件）", cov_enq_on_busy);
    $display("  %-46s: %0d", "走到 S_REQ", cov_state_req);
    $display("  %-46s: %0d", "走到 S_RESP", cov_state_resp);
    $display("  %-46s: %0d", "走到 S_WAIT", cov_state_wait);
    $display("  %-46s: %0d", "Uncache req 握手成交", cov_uncache_req_fire);
    $display("  %-46s: %0d", "MMIO 写回成交(io_mmioOut fire)", cov_mmio_wb);
    $display("  %-46s: %0d", "NC 写回成交(io_ncOut fire)", cov_nc_wb);
    $display("  %-46s: %0d", "0 号条目认领 idResp", cov_slave_ack_e0);
    $display("  %-46s: %0d", "15 号条目认领 idResp", cov_slave_ack_e15);
    $display("  %-46s: %0d", "idResp 有效但 mid 谁都不认领", cov_slave_miss);
    $display("  %-46s: %0d", "S_IDLE/S_REQ 期间被 redirect 直接丢弃", cov_flush_idle);
    $display("  %-46s: %0d", "S_RESP 期间记账 need_flush_q，等 resp 才 flush", cov_flush_deferred);
    $display("  %-46s: %0d", "S_WAIT 期间被 redirect 打中", cov_flush_wait);
    $display("  %-46s: %0d", "redirect level=1（精确冲刷，比相等）", cov_redirect_level);
    $display("  %-46s: %0d", "resp 带 denied", cov_resp_denied);
    $display("  %-46s: %0d", "resp 带 corrupt 且未 denied", cov_resp_corrupt);
    $display("  %-46s: %0d", "MMIO 已就绪但还不是 ROB 头（发不了车）", cov_mmio_head_wait);
    $display("  %-46s: %0d", "MMIO 等到 ROB 头，发车", cov_mmio_head_hit);
    $display("  %-46s: %0d", "io_mmioSelect 抬起", cov_mmioselect);
    $display("checks=%0d errors=%0d", checks, errors);
    if (errors == 0 &&
        cov_reset_pulses > 0 &&
        cov_enq_on_busy > 0 &&
        cov_state_req > 0 &&
        cov_state_resp > 0 &&
        cov_state_wait > 0 &&
        cov_uncache_req_fire > 0 &&
        cov_mmio_wb > 0 &&
        cov_nc_wb > 0 &&
        cov_slave_ack_e0 > 0 &&
        cov_slave_ack_e15 > 0 &&
        cov_slave_miss > 0 &&
        cov_flush_idle > 0 &&
        cov_flush_deferred > 0 &&
        cov_flush_wait > 0 &&
        cov_redirect_level > 0 &&
        cov_resp_denied > 0 &&
        cov_resp_corrupt > 0 &&
        cov_mmio_head_wait > 0 &&
        cov_mmio_head_hit > 0 &&
        cov_mmioselect > 0)
      $display("TEST PASSED");
    else
      $display("TEST FAILED (errors=%0d 或覆盖项为 0)", errors);
    $finish;
  end

endmodule
